#include <stdio.h>

#define MAXN 1000

static int val[MAXN];
static int lft[MAXN];
static int rgt[MAXN];
static int first = 1;

static void inorder(int u)
{
    if (u < 0) {
        return;
    }
    inorder(lft[u]);
    if (!first) {
        printf(" ");
    }
    printf("%d", val[u]);
    first = 0;
    inorder(rgt[u]);
}

int main(void)
{
    int n;
    int root = -1;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 0;
        }
        val[i] = x;
        lft[i] = -1;
        rgt[i] = -1;
        if (root < 0) {
            root = i;
            continue;
        }
        int cur = root;
        for (;;) {
            if (x < val[cur]) {
                if (lft[cur] < 0) {
                    lft[cur] = i;
                    break;
                }
                cur = lft[cur];
            } else {
                if (rgt[cur] < 0) {
                    rgt[cur] = i;
                    break;
                }
                cur = rgt[cur];
            }
        }
    }
    inorder(root);
    printf("\n");
    return 0;
}
